import json

import requests
from taf.internal.impact_radar import log_radar


class ApiClient(object):
    def __init__(self, configuration, token):
        self.configuration = configuration
        self.token = token
        self.base_url = self.configuration.base_url
        self.session = requests.Session()
        self.session.verify = False

    def _make_request(self, method, uri, **kwargs):
        url = self.base_url + uri
        raw_response = kwargs.pop('raw_response', False)
        self.session.headers.update({'Authorization': 'Bearer {}'.format(self.token)})

        log_radar(
            "Sending NADCM request",
            request_method=method,
            request_url=url,
            request_params=kwargs.get("params"),
            request_data=kwargs.get("data"),
            request_json=json.dumps(kwargs.get("json")),
        )

        try:
            response = self.session.request(method=method, url=url, **kwargs)
            response.raise_for_status()
            try:
                if raw_response:
                    return response
                else:
                    return response.json()
            except Exception:
                return response.text
        except requests.exceptions.RequestException as e:
            import traceback
            traceback.print_exc()
            raise RuntimeError(f'Request failed: {format(e)}, reason: {response.text}')

    def send_get_request(self, uri, params=None, **kwargs):
        return self._make_request('get', uri, params=params, **kwargs)

    def send_post_request(self, uri, params=None, data=None, json=None, **kwargs):
        return self._make_request('post', uri, params=params, data=data, json=json, **kwargs)

    def send_put_request(self, uri, data=None, json=None, **kwargs):
        return self._make_request('put', uri, data=data, json=json, **kwargs)

    def send_patch_request(self, uri, data=None, json=None, **kwargs):
        return self._make_request('patch', uri, data=data, json=json, **kwargs)

    def send_delete_request(self, uri, **kwargs):
        return self._make_request('delete', uri, **kwargs)
